export type AskUpdate = { kind: "step"; step: AskStep } | 
/**  The answer, its sources checked; already stored. */
{ kind: "answer"; entry: AskEntry } | 
/**
 *  No answer: the agent failed (its message, for the logs and a detail line), gave
 *  nothing, or took too long.
 */
{ kind: "failed"; message: string | null; timedOut: boolean } | 
/**  Stopped by the user: nothing stored. */
{ kind: "stopped" };

/**
 *  A question to a project progressed (« Demander au projet »): a step, its answer, a failure
 *  or its stop. The last one of a question is `answer`, `failed` or `stopped`.
 */
