	/**  Absolute path of the copy. */
	path: string,
	mimeType: string,
	isImage: boolean,
	/**  Bytes. */
	size: number,
	addedAt: string,
	/**  The copy is still on disk. */
	exists: boolean,
	/**  Where the file stands with the account's server (V2.7 bis): the tile's indicator. */
